function XUiLuckyTenant2Game:UpdateUi(fromOnEnable)
    if not self._Control then
        return
    end

    local uiData = self._Control:GetUiData()
    -- 仅在数据脏时更新棋盘，避免每帧都刷新
    if uiData.IsDirty then
        -- 先调用 Control 层的 UpdateInfo 来更新数据（包括 TotalRound）
        self._Control:UpdateInfo()
        self:UpdateInfo()
        uiData.IsDirty = false

        self:UpdateChessboard()
        if fromOnEnable then
            -- 不立即显示棋盘，等 OnEnable一小段动画之后再显示
            self.PanelChess.gameObject:SetActiveEx(false)
            XScheduleManager.UnSchedule(self._ChessboardShowTimer)
            self._ChessboardShowTimer = XScheduleManager.ScheduleOnce(function()
                self._ChessboardShowTimer = nil
                self.PanelChess.gameObject:SetActiveEx(true)
            end, 400)
        end
    elseif fromOnEnable then 
        self._Control:UpdateBonds()
        self:UpdateBonds()
    end
end

function XUiLuckyTenant2Game:Update(fromOnEnable)
    if self._IsPause then
        self:UpdateAnimation()
        return
    end
    -- 请求中，不进行下一步
    if XMVCA.XLuckyTenant2:IsRequesting() then
        self:UpdateAnimation()
        return
    end

    if not self._Control then
        return
    end

    local uiData = self._Control:GetUiData()
    self:UpdateUi(fromOnEnable)

    local gameState = uiData.GameState
    if self._State ~= gameState then
        self._State = gameState
        self:HandleStateAction()
    end
    self:UpdateAnimation()
end

function XUiLuckyTenant2Game:UpdateAnimation()
    if self._State ~= GameState.Animation then
        return
    end

    if not self._Control then
        return
    end

    -- 使用新的动画管理器
    local deltaTime = CS.UnityEngine.Time.deltaTime
    local isFinished = self._Control:UpdateAnimation(deltaTime, self)

    if isFinished then
        self._Control:FinishAnimation()
        self:ResetTimeScaleTo1()
    end
end

function XUiLuckyTenant2Game:HandleStateAction()
    if not self._Control then
        return
    end

    if self._State == GameState.ShowQuestGoalsOnFirstRound then
        if not XLuaUiManager.IsMaskShow("LuckyTenant2") then
            XLuaUiManager.SetMask(true, "LuckyTenant2")
        end
        self._TimerNextState = XScheduleManager.ScheduleForever(function()
            if self._IsPause then
                return
            end
            XScheduleManager.UnSchedule(self._TimerNextState)
            self._TimerNextState = false
            self._Control:NextGameState()
        end, UiConstants.SCHEDULE_NEXT_STATE_DELAY_MS)
        return
    end

    if self._State == GameState.SelectPiece then
        if self.PanelTaskFinish then
            self.PanelTaskFinish.gameObject:SetActiveEx(false)
        end
        if XLuaUiManager.IsMaskShow("LuckyTenant2") then
            XLuaUiManager.SetMask(false, "LuckyTenant2")
        end
        self._Control:StartSelectPiece()
        return
    end

    if self._State == GameState.CheckQuestCompletionStatus then
        self._TimerNextState = XScheduleManager.ScheduleForever(function()
            if self._IsPause then
                return
            end
            XScheduleManager.UnSchedule(self._TimerNextState)
            self._TimerNextState = false
            self._Control:NextGameState()
        end, UiConstants.SCHEDULE_NEXT_STATE_DELAY_MS)
        return
    end

    if self._State == GameState.ShowNextQuestGoals then
        -- 打开目标达成弹窗
        -- 关闭mask，让弹窗可以点击
        if XLuaUiManager.IsMaskShow("LuckyTenant2") then
            XLuaUiManager.SetMask(false, "LuckyTenant2")
        end

        local game = self._Control._Game
        if game then
            local currentScore = game:GetTotalScore()
            -- 获取刚完成的任务（当前任务），而不是下一个任务
            local currentQuest = game:GetCurrentQuest()
            if currentQuest then
                -- 准备 quest 数据（包括奖励）
                local questData = self._Control:PrepareQuestSuccessData(currentQuest, currentScore)
                XLuaUiManager.Open("UiLuckyTenant2PopupSuccess", questData)
            else
                -- 如果没有当前任务，直接推进状态
                self._Control:NextGameState()
            end
        end
        return
    end

    if self._State == GameState.GameOver then
        if XLuaUiManager.IsMaskShow("LuckyTenant2") then
            XLuaUiManager.SetMask(false, "LuckyTenant2")
        end
        self._Control:OnStagePassed()
        XLuaUiManager.Open("UiLuckyTenant2Settlement")
        return
    end

    if self._State == GameState.NormalClear then
        if XLuaUiManager.IsMaskShow("LuckyTenant2") then
            XLuaUiManager.SetMask(false, "LuckyTenant2")
        end
        self._Control:OnStagePassed()
        XLuaUiManager.Open("UiLuckyTenant2Settlement")
        return
    end

    if self._State == GameState.PerfectClear then
        if XLuaUiManager.IsMaskShow("LuckyTenant2") then
            XLuaUiManager.SetMask(false, "LuckyTenant2")
        end
        self._Control:OnStagePassed()
        XLuaUiManager.Open("UiLuckyTenant2Settlement")
        return
    end

    if self._State == GameState.Animation then
        if not XLuaUiManager.IsMaskShow("LuckyTenant2") then
            XLuaUiManager.SetMask(true, "LuckyTenant2")
        end
        self:PlayAnimation("BtnArrangePress")
        if self._IsSpeedUp then
            local timeScale = self._TimeScaleSpeedUp
            CS.UnityEngine.Time.timeScale = timeScale
        end
        return
    end
end

