function XUiLuckyTenant2Game:UpdateInfo()
    if not self._Control then
        return
    end

    local data = self:GetUiData()
    if not data then
        return
    end

    self._TempScoreIncrement = 0
    self:SetScore(data.Score)
    self:SetAddScore(data.AddScore)
    self:SetDeleteCoin(data.DeleteCoin)
    self:SetRefreshCoin(data.RefreshCoin)

    if self.TxtTaskOrder then
        self.TxtTaskOrder.text = data.QuestCompletedAmount .. "/" .. data.QuestTotalAmount
    end
    if self.TxtNumRound then
        self.TxtNumRound.text = tostring(data.Round)
    end
    if self.TxtTask then
        self.TxtTask.text = XUiHelper.ReplaceTextNewLine(data.QuestDesc)
    end
    -- 统一计算总回合数和当前回合数（用于多个UI元素）
    local currentRound = data.Round or 0
    local totalRound = data.TotalRound or 0
    -- 显示的总回合数最小为 1（TotalRound 在 Control 层已经处理过 quest 上限限制）
    local displayTotalRound = math.max(1, totalRound)
    local lastTargetQuest = self._Control:GetLastTargetQuest()
    local lastTargetQuestRound = lastTargetQuest and lastTargetQuest.Round or 0

    -- 更新当前回合数显示
    if self.TxtTotalTimes then
        currentRound = math.max(1, currentRound)
        self.TxtTotalTimes.text = XUiHelper.GetText("LuckyTenant2TotalTimes", tostring(currentRound))
    end

    -- 更新目标分数显示（当前分数/当前阶段需要的分数），普通状态用 #f1d58f
    if self.TxtTargetScore then
        local currentScore = data.Score or 0
        local targetQuestScore = 0
        targetQuestScore = self._Control:GetTargetQuestScore()
        self.TxtTargetScore.text = tostring(currentScore) .. "/" .. tostring(targetQuestScore)
        self.TxtTargetScore.color = XUiHelper.Hexcolor2Color("f1d58f")
    end

    -- 更新剩余回合数：currentRound 为 0-based，用 1-based 显示回合参与计算，得到 5 4 3 2 1
    if self.TxtTimesRemain then
        local nextQuestRound = 0
        nextQuestRound = self._Control:GetNextQuestRound()
        local remainRound = math.max(1, nextQuestRound - currentRound)
        local upperLimit = nextQuestRound - lastTargetQuestRound
        remainRound = math.min(remainRound, upperLimit)
        remainRound = math.max(0, remainRound)
        self.TxtTimesRemain.text = XUiHelper.GetText("LuckyTenant2TimesRemain", tostring(remainRound))
    end

    -- 更新分数进度条（使用当前分数/当前阶段目标分数），普通状态用 #f1d58f
    if self.ImgBarScore then
        local currentScore = data.Score or 0
        local targetQuestScore = 0
        targetQuestScore = self._Control:GetTargetQuestScore()
        local fillAmount = targetQuestScore > 0 and (currentScore / targetQuestScore) or 0
        fillAmount = math.max(0, math.min(1, fillAmount)) -- 限制在 0-1 之间
        self.ImgBarScore.fillAmount = fillAmount
        self.ImgBarScore.color = XUiHelper.Hexcolor2Color("f1d58f")
        -- 本回合超出上限（当前分数>=阶段目标）时显示 FxUiLuckyTenant202Loop03
        if self.FxUiLuckyTenant202Loop03 then
            self.FxUiLuckyTenant202Loop03.gameObject:SetActiveEx(fillAmount >= 1 and targetQuestScore > 0)
        end
    end

    self:UpdateBagAmount()
    self:UpdateProp()
    self:UpdateQuestList()
    self:UpdateBonds()
end

function XUiLuckyTenant2Game:ForceUpdateBagAmount()
    if not self._Control then
        return
    end

    -- 先更新棋子数量（即使IsBagDirty为false也要更新）
    self._Control:UpdateBagAmount()
    self._Control:UpdateBag()
    local data = self._Control:GetUiData()
    if self.BtnBag then
        local maxPieces = self._Control:GetChessBoardMaxPieces()
        self.BtnBag:SetNameByGroup(0, tostring(data.PiecesAmount) .. " / " .. tostring(maxPieces))
    end
end

function XUiLuckyTenant2Game:UpdateBagAmount()
    if not self._Control then
        return
    end

    self._Control:UpdateBag()
    if self._State ~= GameState.Animation and self._State ~= GameState.Roll then
        local data = self._Control:GetUiData()
        if self.BtnBag then
            local maxPieces = self._Control:GetChessBoardMaxPieces()
            self.BtnBag:SetNameByGroup(0, tostring(data.PiecesAmount) .. " / " .. tostring(maxPieces))
        end
    end
end

function XUiLuckyTenant2Game:UpdateChessboard()
    if not self._Control then
        return
    end

    local data = self._Control:GetUiData()
    if not data or not data.Chessboard then
        return
    end

    if self.GridChess then
        XTool.UpdateDynamicItem(self._Grids, data.Chessboard, self.GridChess, XUiLuckyTenant2GameGridChess, self)
    end
end

---更新当前道具显示（刷新/删除道具在背包中的数量，调用公共 XUiLuckyTenant2PropDisplay）
function XUiLuckyTenant2Game:UpdateProp()
    if self.Prop1 and self._QuestReward then
        XUiLuckyTenant2PropDisplay.UpdatePropDisplay(self._Control, self._QuestReward, self.Prop1, self)
    end
end

function XUiLuckyTenant2Game:UpdateQuestList()
    if not self._Control then
        return
    end

    local data = self:GetUiData()
    if not data or not data.Quests then
        return
    end

    local currentRound = data.Round or 0

    if self.GridRound then
        -- 使用 Control 提供的显示顺序（当前、前一个、后一个、完美/普通通关、最后一个）
        local questsToShow = data.Quests or {}
        XTool.UpdateDynamicItem(self._GridRounds, questsToShow, self.GridRound, XUiLuckyTenant2GameGridRound, self)

        for i = 1, #self._GridRounds do
            local gridRound = self._GridRounds[i]
            local questData = questsToShow[i]
            if gridRound and questData then
                gridRound:Update(questData, currentRound, questsToShow, questData.OriginalIndex or i)
            end
        end
    end
end

---更新羁绊显示（由 Bonds 内部统一从 Control 拉取数据）
function XUiLuckyTenant2Game:UpdateBonds()
    if not self._Bonds then
        return
    end
    self._Bonds:Update()
end

function XUiLuckyTenant2Game:StartGame(record)
    if self._Control then
        self._Control:StartGame(self._StageId, self._Seed, self._IsFirstTimeEntering, record)
        -- 游戏开始后，立即更新一次 UI，确保棋盘数据被显示
        self:UpdateUi()
    end
end

function XUiLuckyTenant2Game:OnClickNextRound()
    if XMVCA.XLuckyTenant2:IsRequesting() then
        return
    end

    if self._State == GameState.CheckQuestCompletionStatus then
        --快进 直接开始选棋
        return
    end

    if XLuaUiManager.IsUiLoad("UiLuckyTenant2OverDetail") then
        return
    end

    if self._State == GameState.Roll then
        if self._Control then
            self._Control:Roll()
        end
        if self.BtnBag then
            self.BtnBag:SetNameByGroup(0, XUiHelper.GetText("LuckyTenantBagPlaying"))
        end
        return
    end
end

function XUiLuckyTenant2Game:OnClickBag()
    if XMVCA.XLuckyTenant2:IsRequesting() then
        return
    end
    if self._State == GameState.Roll then
        XLuaUiManager.Open("UiLuckyTenant2ChessBag")
    end
end

function XUiLuckyTenant2Game:ClosePanelTips()
    if self.PanelTips then
        self.PanelTips.gameObject:SetActiveEx(false)
    end
    if self._Detail then
        self._Detail:Close()
    end
    if self._Bonds and self._Bonds.CloseBondsDetail then
        self._Bonds:CloseBondsDetail()
    end
end

function XUiLuckyTenant2Game:OnClickSpeedUp(event, isOn)
    if not self.BtnSpeedUp then
        return
    end

    local isOn = self.BtnSpeedUp.ButtonState == CS.UiButtonState.Select
    self._IsSpeedUp = isOn
    XSaveTool.SaveData("LuckyTenant2SpeedUp", isOn)
end

function XUiLuckyTenant2Game:_OnGuideEvent(value)
    value = tonumber(value)
    if XLuaUiManager.IsMaskShow("LuckyTenant2") then
        XLuaUiManager.SetMask(false, "LuckyTenant2")
    end
    if value == 0 then
        self._IsPause = true
        return
    end
    if value == 1 then
        self._IsPause = false
        -- 指引恢复时，补执行弹窗关闭时被暂停的 NextGameState（与 1 期 ShowNextQuestGoals 定时器行为一致）
        if self._PendingNextStateFromPopupClose then
            self._PendingNextStateFromPopupClose = false
            self._Control:NextGameState()
            self._Control:SetUiDataDirty(true)
            self:UpdateInfo()
        end
    end
end

-- PlayAnimation/StopAnimation 使用基类 XLuaUi 实现（Timeline/UiProxy），无需在此覆盖

---点击棋盘上的棋子
---@param data table 棋子数据
function XUiLuckyTenant2Game:OnClickPieceOnChessboard(data)
    if not data or not data.IsValid then
        return
    end

    if self.PanelTips then
        self.PanelTips.gameObject:SetActiveEx(true)
    end
    if self.PanelRewardTips then
        self.PanelRewardTips.gameObject:SetActiveEx(false)
    end
    if self._Detail then
        self._Detail:Open()
        self._Detail:Update(data)
    end
end

---根据位置索引获取对应的 grid
---@param position number 位置索引（1-based）
---@return XUiLuckyTenant2GameGridChess|nil
function XUiLuckyTenant2Game:GetGridByPosition(position)
    if not position or position < 1 or position > #self._Grids then
        return nil
    end
    return self._Grids[position]
end

---根据坐标获取对应的 grid
---@param x number X坐标
---@param y number Y坐标
---@return XUiLuckyTenant2GameGridChess|nil
function XUiLuckyTenant2Game:GetGridByXY(x, y)
    if not self._Control then
        return nil
    end

    -- 数据和动画分离：直接通过坐标计算position，不依赖数据
    -- position = (y - 1) * Column + x
    local column = self._Control:GetChessBoardColumn()
    if not column or column <= 0 then
        return nil
    end

    local position = (y - 1) * column + x
    return self:GetGridByPosition(position)
end

-- ==================== 中点刷新机制 ====================
-- 动画播放期间，在动画进行到一半时刷新/隐藏棋子，使视觉效果更自然
-- 即使中点刷新失败，Control:FinishAnimation() 会在动画结束后强制刷新整个棋盘（保底机制）

---从游戏数据刷新指定位置的格子显示
---由 AnimationManager 在 AddPiece/UpdatePiece 动画播放到一半时调用
---@param x number X坐标
---@param y number Y坐标
function XUiLuckyTenant2Game:RefreshGridFromGame(x, y)
    if not self._Control then
        return
    end

    local grid = self:GetGridByXY(x, y)
    if not grid then
        return
    end

    -- 从游戏数据层获取最新的格子数据并刷新显示
    if self._Control.GetCellDisplayDataFromGame then
        local data = self._Control:GetCellDisplayDataFromGame(x, y)
        if data then
            grid:Update(data)
        end
    end
end

---隐藏指定位置的棋子
---由 AnimationManager 在 DeletePiece 动画播放到一半时调用
---@param x number X坐标
---@param y number Y坐标
function XUiLuckyTenant2Game:HideGridPiece(x, y)
    local grid = self:GetGridByXY(x, y)
    if not grid then
        return
    end

    -- 隐藏棋子面板
    if grid.PanelChess and grid.PanelChess.gameObject then
        grid.PanelChess.gameObject:SetActiveEx(false)
    end
end

---播放分数动画
---@param x number X坐标
---@param y number Y坐标
---@param value number 分数值
---@param duration number 动画持续时间（秒）
---@param callback function 完成回调
function XUiLuckyTenant2Game:PlayAnimationGetScore(x, y, value, duration, callback)
    if not self.AnimationGetScore or value <= 0 then
        if callback then
            callback()
        end
        return
    end

    -- 获取对应的 grid
    local grid = self:GetGridByXY(x, y)
    if not grid then
        if callback then
            callback()
        end
        return
    end

    -- 计算目标位置（分数进度条的位置）
    local targetRectTransform = self.ImgBarScore and self.ImgBarScore.transform
    if not targetRectTransform then
        if callback then
            callback()
        end
        return
    end

    local endPosition = targetRectTransform.position
    -- 起始位置使用格子内 TxtCost（分数文字）的位置，飞字才贴合
    local startPosition = (grid.TxtCost and grid.TxtCost.transform) and grid.TxtCost.transform.position or grid.Transform.position

    -- 查找可复用的节点（已隐藏的节点）
    local getScoreGrid = nil
    for key, grid in pairs(self._AnimationGetScore) do
        if grid and grid:IsValid() and not grid:IsNodeShow() then
            -- 找到已隐藏的节点，复用
            getScoreGrid = grid
            break
        end
    end

    -- 如果没有可复用的节点，创建一个新的
    if not getScoreGrid then
        local ui = CS.UnityEngine.Object.Instantiate(self.AnimationGetScore, self.AnimationGetScore.transform.parent)
        ui.gameObject:SetActiveEx(false) -- 先设置为 false，由 Open() 来激活
        getScoreGrid = XUiLuckyTenant2GameAnimationGetScore.New(ui, self)
        -- 使用时间戳作为 key 确保唯一性
        local key = string.format("score_%d",
            math.floor(CS.UnityEngine.Time.frameCount * 1000 + (CS.UnityEngine.Time.time * 1000) % 1000))
        self._AnimationGetScore[key] = getScoreGrid
    end

    -- 设置起始位置
    if getScoreGrid.Transform then
        getScoreGrid.Transform.position = startPosition
    end
    -- 使用 Open() 方法显示节点（会触发 OnStart -> Update，所以要在 Open 之后设置文本）
    if getScoreGrid then
        getScoreGrid:Open()
    end
    -- 在 Open() 之后设置文本（避免被 Update() 覆盖）
    if getScoreGrid and getScoreGrid.TextGetScore then
        getScoreGrid.TextGetScore.text = tostring(value)
    end

    -- 播放移动动画
    if getScoreGrid.Transform then
        XUiHelper.DoWorldMove(getScoreGrid.Transform, endPosition, duration, XUiHelper.EaseType.Linear, function()
            -- 动画完成后，隐藏节点以便复用
            if getScoreGrid then
                getScoreGrid:Close()
            end

            -- 如果正在播放棋子分数动画，不在这里更新分数（由 PlayNextPieceScoreAnimation 处理）
            -- 否则，正常更新分数显示
            if not self._IsPlayingPieceScoreAnimation then
                if self._Control then
                    local uiData = self._Control:GetUiData()
                    if uiData then
                        self:SetScore(uiData.Score or 0)
                        self:SetAddScore(uiData.AddScore or 0)
                    end
                end
            end

            if callback then
                callback()
            end

            -- 分数增量动画
            self._TempScoreIncrement = self._TempScoreIncrement + math.ceil(value)
            local data = self:GetUiData()
            if data then
                local currentScore = (data.Score or 0) + self._TempScoreIncrement
                local targetQuestScore = self._Control:GetTargetQuestScore()
                self.TxtTargetScore.text = tostring(currentScore) .. "/" .. tostring(targetQuestScore)
                local fillAmount = targetQuestScore > 0 and (currentScore / targetQuestScore) or 0
                fillAmount = math.max(0, math.min(1, fillAmount)) -- 限制在 0-1 之间
                self.ImgBarScore.fillAmount = fillAmount
            end
        end)
    else
        -- 如果没有 Transform，直接完成
        if callback then
            callback()
        end
    end
end

---播放获得道具动画
---@param x number X坐标
---@param y number Y坐标
---@param itemId number 道具ID
---@param duration number 动画持续时间（秒）
---@param callback function 完成回调
function XUiLuckyTenant2Game:PlayAnimationGetItem(x, y, itemId, duration, callback)
    if not self.AnimationGetItem or not itemId or itemId <= 0 then
        if callback then
            callback()
        end
        return
    end

    -- 获取对应的 grid
    local grid = self:GetGridByXY(x, y)
    if not grid then
        if callback then
            callback()
        end
        return
    end

    -- 计算目标位置（背包按钮的位置）
    local targetRectTransform = self.BtnBag and self.BtnBag.transform
    if not targetRectTransform then
        if callback then
            callback()
        end
        return
    end

    local endPosition = targetRectTransform.position
    local startPosition = grid.Transform.position

    -- 查找可复用的节点（已隐藏的节点）
    local getItemGrid = nil
    for key, gridItem in pairs(self._AnimationGetItem) do
        if gridItem and gridItem:IsValid() and not gridItem:IsNodeShow() then
            -- 找到已隐藏的节点，复用
            getItemGrid = gridItem
            break
        end
    end

    -- 如果没有可复用的节点，创建一个新的
    if not getItemGrid then
        local ui = CS.UnityEngine.Object.Instantiate(self.AnimationGetItem, self.AnimationGetItem.transform.parent)
        ui.gameObject:SetActiveEx(false) -- 先设置为 false，由 Open() 来激活
        getItemGrid = XUiLuckyTenant2GameAnimationGetItem.New(ui, self)
        -- 使用时间戳作为 key 确保唯一性
        local key = string.format("item_%d",
            math.floor(CS.UnityEngine.Time.frameCount * 1000 + (CS.UnityEngine.Time.time * 1000) % 1000))
        self._AnimationGetItem[key] = getItemGrid
    end

    -- 更新动画数据（设置图标等）
    if getItemGrid and getItemGrid.IconGetItem then
        -- 这里可以根据 itemId 设置对应的图标
        -- 暂时留空，后续可以根据需求实现
    end

    -- 设置起始位置
    if getItemGrid.Transform then
        getItemGrid.Transform.position = startPosition
    end
    -- 使用 Open() 方法显示节点
    if getItemGrid then
        getItemGrid:Open()
    end

    -- 播放移动动画
    if getItemGrid.Transform then
        XUiHelper.DoWorldMove(getItemGrid.Transform, endPosition, duration, XUiHelper.EaseType.Linear, function()
            -- 动画完成后，隐藏节点以便复用
            if getItemGrid then
                getItemGrid:Close()
            end

            if callback then
                callback()
            end
        end)
    else
        -- 如果没有 Transform，直接完成
        if callback then
            callback()
        end
    end
end

---播放添加棋子动画（生成棋子）
---刷新由 AnimationManager 中点刷新机制控制（RefreshGridFromGame）
---@param pieceId number 棋子ID
---@param x number|nil X坐标（可选）
---@param y number|nil Y坐标（可选）
function XUiLuckyTenant2Game:PlayAnimationAddPiece(pieceId, x, y)
    if not x or not y then
        return
    end
    local grid = self:GetGridByXY(x, y)
    if not grid then
        return
    end
    -- 播放该格子的生成/出现特效；有棋子出生在 GridChess 时播放 ChessBorn
    if grid.PlayAnimation then
        grid:PlayAnimation("ChessBorn")
    end
    if grid.ShowEffect then
        grid:ShowEffect()
    end
end

---播放更新棋子动画（属性变化：值、等级、状态等）
---@param pieceUid number 棋子UID
---@param skillId number|nil 来源技能ID（动画组传入，用于日志）
---@param refreshImmediately boolean|nil 是否立即刷新（默认false，由AnimationManager控制刷新时机）
function XUiLuckyTenant2Game:PlayAnimationUpdatePiece(pieceUid, skillId, refreshImmediately)
    if not pieceUid or pieceUid <= 0 then
        return
    end

    if not self._Control then
        return
    end

    local uiData = self._Control:GetUiData()
    if not uiData or not uiData.Chessboard then
        return
    end

    -- 从棋盘数据中查找对应的棋子（快照中仍有该棋子，位置未变）
    local pieceData = nil
    for _, chessData in ipairs(uiData.Chessboard) do
        if chessData.Uid == pieceUid then
            pieceData = chessData
            break
        end
    end

    if not pieceData then
        return
    end

    local grid = self:GetGridByPosition(pieceData.Position)
    if not grid then
        return
    end

    local x, y = pieceData.X, pieceData.Y

    -- 如果需要立即刷新（兼容旧逻辑）
    if refreshImmediately and x and y and self._Control.GetCellDisplayDataFromGame then
        local data = self._Control:GetCellDisplayDataFromGame(x, y)
        if data then
            grid:Update(data)
        end
    end
end

---根据 pieceUid 或 (x,y) 获取对应格子，用于播放格子动画
---@param pieceUid number 棋子UID（可选，有则从棋盘数据查位置）
---@param x number X坐标（可选）
---@param y number Y坐标（可选）
---@return XUiLuckyTenant2GameGridChess|nil
function XUiLuckyTenant2Game:GetGridByPieceUidOrXY(pieceUid, x, y)
    if x and y and x > 0 and y > 0 then
        return self:GetGridByXY(x, y)
    end
    if not pieceUid or pieceUid <= 0 or not self._Control then
        return nil
    end
    local uiData = self._Control:GetUiData()
    if not uiData or not uiData.Chessboard then
        return nil
    end
    for _, chessData in ipairs(uiData.Chessboard) do
        if chessData.Uid == pieceUid then
            return self:GetGridByPosition(chessData.Position)
        end
    end
    return nil
end

---单回合内该格子该类型特效是否已播过（用于同格同类型只播一次）
---@param effectType string GridEffectType 枚举值（Countdown/Delete/WeaponSkill/Infection/RoleEliminate）
---@param gridKey string 格子键，如 "x,y" 或 "uid_xxx"
---@return boolean
function XUiLuckyTenant2Game:_WasGridEffectPlayedInGroup(effectType, gridKey)
    if not self._GridEffectPlayedInGroup or not effectType or not gridKey then
        return false
    end
    local set = self._GridEffectPlayedInGroup[effectType]
    return set and set[gridKey] == true
end

---标记单回合内该格子该类型特效已播
---@param effectType string
---@param gridKey string
function XUiLuckyTenant2Game:_MarkGridEffectPlayedInGroup(effectType, gridKey)
    if not effectType or not gridKey then
        return
    end
    if not self._GridEffectPlayedInGroup then
        self._GridEffectPlayedInGroup = {}
    end
    if not self._GridEffectPlayedInGroup[effectType] then
        self._GridEffectPlayedInGroup[effectType] = {}
    end
    self._GridEffectPlayedInGroup[effectType][gridKey] = true
end

---清空格子特效播放记录（每回合动画开始前调用）
function XUiLuckyTenant2Game:ClearGridEffectPlayedInGroup()
    self._GridEffectPlayedInGroup = nil
end

---播放主动发动技能动画（发动技能的棋子）
---@param pieceUid number 棋子UID
---@param x number X坐标
---@param y number Y坐标
---@param skillId number 技能配置ID（用于武器类/角色升级类技能播放 FxUiLuckyTenant213）
function XUiLuckyTenant2Game:PlayAnimationActivateSkillEnable(pieceUid, x, y, skillId)
    local grid = self:GetGridByPieceUidOrXY(pieceUid, x, y)
    if not grid then return end
    local gridKey = (x and y and x > 0 and y > 0) and (tostring(x) .. "," .. tostring(y)) or (grid._Data and grid._Data.X and grid._Data.Y and (tostring(grid._Data.X) .. "," .. tostring(grid._Data.Y))) or ("uid_" .. tostring(pieceUid))
    -- 武器类（Type401-407）、角色升级（Type301）发动时复用 FxUiLuckyTenant213；单回合内同一格子只播一次（skillId 需转换为 skillType 再比较）
    local skillType = self._Control and self._Control:GetSkillTypeBySkillId(skillId)
    local isActivateSkill213 = skillType and ((skillType >= Skill.Type401 and skillType <= Skill.Type407) or skillType == Skill.Type301)
    if isActivateSkill213 and not self:_WasGridEffectPlayedInGroup(GridEffectType.WeaponSkill, gridKey) then
        self:_MarkGridEffectPlayedInGroup(GridEffectType.WeaponSkill, gridKey)
        grid:PlayEffectWeaponSkill(skillId)
    end
    -- 宝盒品质提升（Type507品质+1、Type502重生品质提升）时播放 FxUiLuckyTenant213；单回合内同一格子只播一次
    if skillType then
        if skillType == Skill.Type507 and not self:_WasGridEffectPlayedInGroup(GridEffectType.BoxUpgrade, gridKey) then
            self:_MarkGridEffectPlayedInGroup(GridEffectType.BoxUpgrade, gridKey)
            grid:PlayEffectBoxUpgrade(skillId)
        elseif skillType == Skill.Type502 and not self:_WasGridEffectPlayedInGroup(GridEffectType.BoxUpgrade, gridKey) then
            self:_MarkGridEffectPlayedInGroup(GridEffectType.BoxUpgrade, gridKey)
            grid:PlayEffectBoxReborn(skillId)
        end
    end
    grid:PlayAnimation("ActivateSkillEnable")
end

---播放受技能影响动画（被技能影响的棋子）
---@param pieceUid number 棋子UID（可选，无则用 x,y 定位）
---@param x number X坐标
---@param y number Y坐标
---@param skillId number 技能配置ID（可选，用于传染/角色消除播放对应特效）
---@param fromPieceUid number|nil 主动释放技能的棋子UID（可选，传染特效优先在该棋子播放）
function XUiLuckyTenant2Game:PlayAnimationAffectedBySkillEnable(pieceUid, x, y, skillId, fromPieceUid)
    local grid = self:GetGridByPieceUidOrXY(pieceUid, x, y)
    if not grid then return end

    local gridKey = (x and y and x > 0 and y > 0) and (tostring(x) .. "," .. tostring(y)) or (grid._Data and grid._Data.X and grid._Data.Y and (tostring(grid._Data.X) .. "," .. tostring(grid._Data.Y))) or ("uid_" .. tostring(pieceUid))
    local skillType = self._Control and skillId and self._Control:GetSkillTypeBySkillId(skillId)

    -- 子虫/红潮传染（Type207/208/601）播放传染特效；角色消除（Type304/305/306）播放被角色消除特效；
    -- 去重规则：同回合同类型下，同一UID只播一次（无UID时回退到坐标）
    if skillType then
        local isInfection = skillType == Skill.Type207 or skillType == Skill.Type208 or skillType == Skill.Type601
        local isRoleEliminate = skillType == Skill.Type304 or skillType == Skill.Type305 or skillType == Skill.Type306

        if isInfection then
            -- 传染特效播在“主动释放技能”的棋子上；找不到时回退到受影响棋子
            local infectionGrid = grid
            local infectionEffectKey = (pieceUid and pieceUid > 0) and ("uid_" .. tostring(pieceUid)) or gridKey
            if fromPieceUid and fromPieceUid > 0 then
                local sourceGrid = self:GetGridByPieceUidOrXY(fromPieceUid)
                if sourceGrid then
                    infectionGrid = sourceGrid
                end
                infectionEffectKey = "uid_" .. tostring(fromPieceUid)
            end
            if not self:_WasGridEffectPlayedInGroup(GridEffectType.Infection, infectionEffectKey) then
                self:_MarkGridEffectPlayedInGroup(GridEffectType.Infection, infectionEffectKey)
                infectionGrid:PlayEffectInfectionSkill(skillId)
            end
        elseif isRoleEliminate then
            local roleUid = pieceUid or (grid and grid._Data and grid._Data.Uid) or 0
            local roleEffectKey = (roleUid and roleUid > 0) and ("uid_" .. tostring(roleUid)) or gridKey
            local shouldPlay = skillType == Skill.Type305 or not self:_WasGridEffectPlayedInGroup(GridEffectType.RoleEliminate, roleEffectKey)
            if shouldPlay then
                self:_MarkGridEffectPlayedInGroup(GridEffectType.RoleEliminate, roleEffectKey)
                grid:PlayEffectRoleEliminate(skillId)
            end
        end
    end

    if grid.PlayAnimation then
        grid:PlayAnimation("AffectedBySkillEnable")
    end
end

---播放删除棋子动画（包含完整的消除过程：晃动源棋子 -> 高亮目标棋子 -> 删除动画）
---@param pieceUid number 被删除的棋子UID
---@param x number X坐标
---@param y number Y坐标
---@param fromPieceUid number 发出消除动作的棋子UID（可选）
---@param pieceId number 被删棋子ID（可选，用于宝盒/非宝盒消除特效 208/209）
---@param skillId number|nil 来源技能ID（动画组传入，用于日志）
---@param hideImmediately boolean|nil 是否立即执行隐藏动画（默认true，false时由AnimationManager控制隐藏时机）
function XUiLuckyTenant2Game:PlayAnimationDeletePiece(pieceUid, x, y, fromPieceUid, pieceId, skillId, hideImmediately)
    -- 默认立即执行隐藏动画（兼容旧逻辑）
    if hideImmediately == nil then
        hideImmediately = true
    end

    -- 在被消除的格子上播放消除特效（宝盒 209，其它 208）；单回合内同一格子只播一次（优先按UID去重，其次按坐标）
    local grid = self:GetGridByPieceUidOrXY(pieceUid, x, y)
    local gridKey = (pieceUid and pieceUid > 0) and ("uid_" .. tostring(pieceUid))
        or ((x and y) and (tostring(x) .. "," .. tostring(y)) or nil)
    if grid and not self:_WasGridEffectPlayedInGroup(GridEffectType.Delete, gridKey) then
        self:_MarkGridEffectPlayedInGroup(GridEffectType.Delete, gridKey)
        if pieceId and self._Control and self._Control._Model then
            local pieceType = self._Control._Model:GetLuckyTenant2ChessTypeById(pieceId)
            local XLuckyTenant2Enum = require("XModule/XLuckyTenant2/Game/XLuckyTenant2Enum")
            if pieceType == XLuckyTenant2Enum.PieceType.Box then
                grid:PlayEffectEliminatedBox(skillId)
            else
                grid:PlayEffectEliminatedNormal(skillId)
            end
        else
            grid:PlayEffectEliminatedNormal(skillId)
        end
    end

    -- 如果不立即执行隐藏动画，只播放特效，由AnimationManager控制隐藏时机
    if not hideImmediately then
        return
    end

    -- 步骤1: 如果有fromPieceUid，先晃动发出消除动作的棋子
    if fromPieceUid and fromPieceUid > 0 then
        self:_PlayShakeAnimationForPiece(fromPieceUid, function()
            -- 步骤2: 高亮被消除的棋子
            self:_PlayHighlightAnimationForPiece(pieceUid, x, y, function()
                -- 步骤3: 播放删除动画
                self:_PlayDeleteAnimationForPiece(pieceUid, x, y)
            end)
        end)
    else
        -- 如果没有fromPieceUid，直接高亮然后删除
        self:_PlayHighlightAnimationForPiece(pieceUid, x, y, function()
            self:_PlayDeleteAnimationForPiece(pieceUid, x, y)
        end)
    end
end

---播放晃动动画（用于发出消除动作的棋子）
---@param pieceUid number 棋子UID
---@param callback function 完成回调
function XUiLuckyTenant2Game:_PlayShakeAnimationForPiece(pieceUid, callback)
    if not pieceUid or pieceUid <= 0 then
        if callback then callback() end
        return
    end

    -- 从棋盘数据中查找对应的棋子位置
    if not self._Control then
        if callback then callback() end
        return
    end

    local uiData = self._Control:GetUiData()
    if not uiData or not uiData.Chessboard then
        if callback then callback() end
        return
    end

    -- 查找对应的棋子数据
    local pieceData = nil
    for _, chessData in ipairs(uiData.Chessboard) do
        if chessData.Uid == pieceUid then
            pieceData = chessData
            break
        end
    end

    if not pieceData then
        if callback then callback() end
        return
    end

    local grid = self:GetGridByPosition(pieceData.Position)
    if not grid then
        if callback then callback() end
        return
    end

    local targetTransform = nil
    if grid.PanelChess and grid.PanelChess.gameObject then
        targetTransform = grid.PanelChess.transform
    elseif grid.Root and grid.Root.gameObject then
        targetTransform = grid.Root.transform
    end

    if not targetTransform then
        if callback then callback() end
        return
    end

    -- 使用简单的缩放动画模拟晃动效果（可以后续优化为真正的晃动动画）
    local originalScale = targetTransform.localScale
    local shakeScale = CS.UnityEngine.Vector3(originalScale.x * UiConstants.SHAKE_SCALE_FACTOR, originalScale.y * UiConstants.SHAKE_SCALE_FACTOR, originalScale.z)
    local duration = UiConstants.SHAKE_ANIMATION_DURATION

    -- 快速放大然后恢复
    XUiHelper.DoScale(targetTransform, originalScale, shakeScale, duration / 2, XUiHelper.EaseType.Sin, function()
        XUiHelper.DoScale(targetTransform, shakeScale, originalScale, duration / 2, XUiHelper.EaseType.Sin, function()
            if callback then callback() end
        end)
    end)
end

---播放高亮动画（用于被消除的棋子）
---@param pieceUid number 棋子UID
---@param x number X坐标
---@param y number Y坐标
---@param callback function 完成回调
function XUiLuckyTenant2Game:_PlayHighlightAnimationForPiece(pieceUid, x, y, callback)
    local grid = self:GetGridByXY(x, y)
    if not grid then
        if callback then callback() end
        return
    end

    local targetTransform = nil
    if grid.PanelChess and grid.PanelChess.gameObject then
        targetTransform = grid.PanelChess.transform
    elseif grid.Root and grid.Root.gameObject then
        targetTransform = grid.Root.transform
    end

    if not targetTransform then
        if callback then callback() end
        return
    end

    -- 使用简单的缩放动画模拟高亮效果（可以后续优化为颜色或发光效果）
    local originalScale = targetTransform.localScale
    local highlightScale = CS.UnityEngine.Vector3(originalScale.x * UiConstants.HIGHLIGHT_SCALE_FACTOR, originalScale.y * UiConstants.HIGHLIGHT_SCALE_FACTOR, originalScale.z)
    local duration = UiConstants.HIGHLIGHT_ANIMATION_DURATION

    -- 放大然后恢复
    XUiHelper.DoScale(targetTransform, originalScale, highlightScale, duration / 2, XUiHelper.EaseType.Sin, function()
        XUiHelper.DoScale(targetTransform, highlightScale, originalScale, duration / 2, XUiHelper.EaseType.Sin,
            function()
                if callback then callback() end
            end)
    end)
end

---播放删除动画（棋子消失）
---@param pieceUid number 棋子UID
---@param x number X坐标
---@param y number Y坐标
function XUiLuckyTenant2Game:_PlayDeleteAnimationForPiece(pieceUid, x, y)
    local grid = self:GetGridByXY(x, y)
    if not grid then
        return
    end

    -- 使用 PanelChess 或 Root 播放缩放消失动画
    local targetTransform = nil
    local targetGameObject = nil
    local originalScale = nil

    if grid.PanelChess and grid.PanelChess.gameObject then
        targetTransform = grid.PanelChess.transform
        targetGameObject = grid.PanelChess.gameObject
        originalScale = targetTransform.localScale
    elseif grid.Root and grid.Root.gameObject then
        targetTransform = grid.Root.transform
        targetGameObject = grid.Root.gameObject
        originalScale = targetTransform.localScale
    end

    if not targetTransform or not targetGameObject then
        return
    end

    -- 使用 XUiHelper.DoScale 播放缩放消失动画
    local zeroScale = CS.UnityEngine.Vector3.zero
    local duration = UiConstants.DELETE_ANIMATION_DURATION

    XUiHelper.DoScale(targetTransform, originalScale, zeroScale, duration, XUiHelper.EaseType.Sin, function()
        -- 动画完成后，确保对象被隐藏并恢复原始缩放
        if targetGameObject and targetTransform then
            targetGameObject:SetActiveEx(false)
            targetTransform.localScale = originalScale
        end
    end)
end

function XUiLuckyTenant2Game:OnBtnBackClick()
    XLuaUiManager.Open("UiLuckyTenant2PopupNormal")
end

function XUiLuckyTenant2Game:ResetTimeScaleTo1()
    CS.UnityEngine.Time.timeScale = UiConstants.TIME_SCALE_NORMAL
end

function XUiLuckyTenant2Game:PlayEffectLevel0()
    if self.FxUiLuckyTenant217 then
        self.FxUiLuckyTenant217.gameObject:SetActiveEx(false)
        self.FxUiLuckyTenant217.gameObject:SetActiveEx(true)
    end
end

function XUiLuckyTenant2Game:_OnGuideSkip()
    if not XDataCenter.GuideManager.CheckIsInGuide() then
        self._IsPause = false
    end
end

return XUiLuckyTenant2Game
